package io.tenvyr.control.engine;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import io.tenvyr.platform.*;
import java.sql.Savepoint;
import java.time.Instant;
import static io.tenvyr.control.engine.EngineFacts.*;

/** The inbox identity and terminal state commit together. A handler error leaves no partial terminal truth. */
public final class ResultInboxService {
  public record Application(String disposition,String executionId,String stepId){}
  private final Db db;private final EngineAuthority authority;
  public ResultInboxService(Db db,EngineAuthority authority){this.db=db;this.authority=authority;}
  public Application apply(ObjectNode result,ObjectNode transport){String hash=Json.hash(result);TransportIdentity source=TransportIdentity.of(transport);return db.transaction(tx->{
    ObjectNode attempt=tx.one("SELECT * FROM step_attempts WHERE \"invocationId\"=? FOR UPDATE",result.path("invocationId").asText());if(attempt==null||!attempt.path("executionId").asText().equals(result.path("executionId").asText())||!attempt.path("logicalStepId").asText().equals(result.path("stepExecutionId").asText()))return new Application("ignored",null,null);
    tx.execute("INSERT INTO result_inbox (\"invocationId\",\"stepAttemptId\",\"payloadHash\",payload,\"sourceAdapter\",\"sourceScope\",\"sourceMessageId\",status,\"receivedAt\") VALUES (?,?,?,?,?,?,?,'RECEIVED',now()) ON CONFLICT DO NOTHING",result.path("invocationId").asText(),attempt.path("id").asText(),hash,result,source.adapter(),source.scope(),source.messageId());
    ObjectNode inbox=tx.one("SELECT * FROM result_inbox WHERE \"invocationId\"=? FOR UPDATE",result.path("invocationId").asText());if(inbox==null){ObjectNode transportInbox=source.messageId()==null?null:tx.one("SELECT * FROM result_inbox WHERE \"sourceAdapter\"=? AND \"sourceScope\"=? AND \"sourceMessageId\"=? FOR UPDATE",source.adapter(),source.scope(),source.messageId());if(transportInbox==null)throw new IllegalStateException("Result inbox insertion did not produce a canonical row");conflict(tx,result,transportInbox,hash,source);return new Application("conflict",null,null);}
    if(!inbox.path("payloadHash").asText().equals(hash)){conflict(tx,result,inbox,hash,source);return new Application("conflict",null,null);}
    ObjectNode logical=tx.one("SELECT * FROM step_executions WHERE id=? FOR UPDATE",attempt.path("logicalStepId").asText());if(logical==null)throw new IllegalStateException("Result refers to missing logical step");if(inbox.path("status").asText().equals("APPLIED"))return new Application("duplicate",attempt.path("executionId").asText(),logical.path("stepId").asText());
    ObjectNode execution=tx.one("SELECT * FROM executions WHERE id=? FOR UPDATE",attempt.path("executionId").asText());if(execution==null)throw new IllegalStateException("Result refers to missing execution");if(execution.path("status").asText().equals("CANCELLED")){reject(tx,inbox,"Execution cancellation is already authoritative");return new Application("conflict",null,null);}
    ObjectNode revision=tx.one("SELECT * FROM execution_plan_revisions WHERE id=?",attempt.path("planRevisionId").asText());ObjectNode config=revision==null?null:step(revision.path("plan"),logical.path("stepId").asText());String terminal=switch(result.path("status").asText()){case "succeeded"->"SUCCESS";case "timed_out"->"TIMED_OUT";case "cancelled"->"CANCELLED";default->"FAILED";};boolean alreadyTerminal=TERMINAL_ATTEMPT.contains(attempt.path("status").asText());if(alreadyTerminal&&!attempt.path("status").asText().equals(terminal)){reject(tx,inbox,"A different terminal outcome is already authoritative");return new Application("conflict",null,null);}
    JsonNode stateEvidence=null;String postcondition=null;boolean live=execution.path("status").asText().equals("RUNNING"),success=result.path("status").asText().equals("succeeded");
    if(live&&success&&config!=null&&config.path("stateWrites").isArray()&&!config.path("stateWrites").isEmpty()){stateEvidence=authority.applyStateWrites(tx.connection(),execution,config.get("stateWrites"),result.get("output"));if(stateEvidence.path("disposition").asText().equals("rejected")){terminal="FAILED";postcondition="TENVYR_STATE_WRITE_REJECTED: "+stateEvidence.path("rejectionCode").asText();}}
    if(live&&success&&config!=null&&config.path("planner").asBoolean()&&postcondition==null&&!alreadyTerminal){Savepoint save=tx.connection().setSavepoint();try{authority.proposePlan(tx.connection(),execution.path("id").asText(),result.get("output"),"planner");tx.connection().releaseSavepoint(save);}catch(Exception error){tx.connection().rollback(save);terminal="FAILED";postcondition="PLANNER_PROPOSAL_INVALID: "+message(error);}}
    Instant now=Instant.now();String error=postcondition==null?error(result):postcondition;if(!alreadyTerminal){int affected=tx.execute("UPDATE step_attempts SET status=?,\"terminalAt\"=?,result=?,error=?,\"terminationReason\"=?,efficiency=? WHERE id=? AND status NOT IN "+ATTEMPT_TERMINAL_SQL,terminal,now,success?result.get("output"):null,error,postcondition==null?terminationReason(result):postcondition,authority.completeEfficiency(attempt.get("efficiency"),result,attempt),attempt.path("id").asText());if(affected!=1)throw new IllegalStateException("Attempt terminal transition lost its guard");authority.settleBudget(tx.connection(),attempt.path("invocationId").asText(),result.get("usage"));}
    tx.execute("UPDATE dispatch_outbox SET status='COMPLETED',\"leaseExpiresAt\"=NULL,\"leaseToken\"=NULL WHERE \"stepAttemptId\"=? AND status IN ('PENDING','LEASED','DISPATCHED')",attempt.path("id").asText());boolean retry=live&&(terminal.equals("FAILED")||terminal.equals("TIMED_OUT"))&&config!=null&&config.path("onFailure").asText().equals("retry")&&attempt.path("attemptNumber").asInt()<logical.path("maxAttempts").asInt();String status=terminal.equals("SUCCESS")?"COMPLETED":terminal.equals("CANCELLED")?"CANCELLED":retry?"RETRYING":"FAILED";
    tx.update("step_executions",logical.path("id").asText(),Json.object("status",status,"output",terminal.equals("SUCCESS")?result.get("output"):null,"error",error,"endTime",retry?null:now.toString(),"nextAttemptAt",retry?now.toString():null));
    if(!TERMINAL_EXECUTION.contains(execution.path("status").asText())){if(!retry&&status.equals("FAILED")&&(config==null||!config.path("onFailure").asText().equals("continue")))tx.update("executions",execution.path("id").asText(),Json.object("status","FAILED","endTime",now.toString(),"terminationReason",error));else if(status.equals("CANCELLED"))tx.update("executions",execution.path("id").asText(),Json.object("status","CANCELLED","endTime",now.toString(),"terminationReason",terminationReason(result)));}
    int ordinal=0;for(JsonNode descriptor:result.path("artifacts"))tx.execute("INSERT INTO artifacts (\"resultInboxId\",\"descriptorOrdinal\",\"descriptorHash\") VALUES (?,?,?) ON CONFLICT DO NOTHING",inbox.path("id").asText(),ordinal++,Json.hash(descriptor));
    if(stateEvidence!=null)tx.execute("INSERT INTO state_write_evidence (\"executionId\",\"stepAttemptId\",\"resultInboxId\",\"priorVersion\",\"resultVersion\",disposition,\"mappingHash\",\"rejectionCode\") VALUES (?,?,?,?,?,?,?,?) ON CONFLICT DO NOTHING",execution.path("id").asText(),attempt.path("id").asText(),inbox.path("id").asText(),stateEvidence.path("priorVersion").asInt(),stateEvidence.path("resultVersion").asInt(),stateEvidence.path("disposition").asText(),Json.text(stateEvidence,"mappingHash"),Json.text(stateEvidence,"rejectionCode"));
    if(config!=null&&config.path("delegation").asText().equals("observed")&&result.path("delegation").isArray()&&!result.path("delegation").isEmpty()){Savepoint save=tx.connection().setSavepoint();try{authority.recordDelegation(tx.connection(),attempt,config,result.get("delegation"));tx.connection().releaseSavepoint(save);}catch(Exception evidenceError){tx.connection().rollback(save);}}
    tx.update("result_inbox",inbox.path("id").asText(),Json.object("status","APPLIED","appliedAt",now.toString(),"lastApplicationError",postcondition));return new Application("applied",attempt.path("executionId").asText(),logical.path("stepId").asText());
  });}
  private void conflict(Db tx,ObjectNode result,ObjectNode inbox,String hash,TransportIdentity s){tx.execute("INSERT INTO result_conflicts (\"invocationId\",\"resultInboxId\",\"payloadHash\",payload,\"sourceAdapter\",\"sourceScope\",\"sourceMessageId\",\"receivedAt\") VALUES (?,?,?,?,?,?,?,now()) ON CONFLICT DO NOTHING",result.path("invocationId").asText(),inbox.path("id").asText(),hash,result,s.adapter(),s.scope(),s.messageId());}
  private void reject(Db tx,ObjectNode inbox,String reason){tx.update("result_inbox",inbox.path("id").asText(),Json.object("status","REJECTED","lastApplicationError",reason));}
  private String error(ObjectNode result){JsonNode e=result.get("error");return e==null||e.isNull()?null:e.path("code").asText()+": "+e.path("message").asText();}
  private String terminationReason(ObjectNode result){return switch(result.path("status").asText()){case "cancelled"->"Worker cancelled the attempt";case "timed_out"->"Worker reported a timeout";default->error(result);};}
}
